# Custom Collections

Build your own collection type for custom data sources.

## When to Build Custom

- Integrating with unsupported sync engine
- Custom caching requirements
- Specialized data source (WebSocket, IndexedDB, etc.)
- Unique persistence patterns

## Collection Interface

Implement the `Collection` interface from `@tanstack/db`:

```tsx
interface Collection<TData, TKey> {
  // Identity
  id: string

  // Read operations
  get(key: TKey): TData | undefined
  has(key: TKey): boolean
  toArray: TData[]
  size: number

  // Write operations
  insert(item: TData | TData[], options?: MutationOptions): Transaction
  update(
    key: TKey | TKey[],
    updater: (draft: TData) => void,
    options?: MutationOptions,
  ): Transaction
  delete(key: TKey | TKey[], options?: MutationOptions): Transaction

  // State
  state: CollectionState

  // Utilities
  utils: CollectionUtils
}
```

## Basic Structure

```tsx
import { createCollection, type CollectionOptions } from '@tanstack/db'

export function myCollectionOptions<TData, TKey>(
  options: MyCollectionConfig<TData, TKey>,
): CollectionOptions<TData, TKey> {
  return {
    id: options.id,
    getKey: options.getKey,
    schema: options.schema,

    // Sync configuration
    sync: {
      // Called to start syncing data
      start: async (collection) => {
        // Set up data sync
        const cleanup = subscribeToDataSource((data) => {
          collection.utils.directWrite('insert', data)
        })

        // Return cleanup function
        return cleanup
      },

      // Called to stop syncing
      stop: async (cleanup) => {
        cleanup?.()
      },
    },

    // Mutation handlers
    onInsert: options.onInsert,
    onUpdate: options.onUpdate,
    onDelete: options.onDelete,
  }
}
```

## Example: WebSocket Collection

```tsx
export function websocketCollectionOptions<TData, TKey>(config: {
  id: string
  url: string
  getKey: (item: TData) => TKey
  schema?: StandardSchema
  onInsert?: MutationFn
  onUpdate?: MutationFn
  onDelete?: MutationFn
}): CollectionOptions<TData, TKey> {
  return {
    id: config.id,
    getKey: config.getKey,
    schema: config.schema,

    sync: {
      start: async (collection) => {
        const ws = new WebSocket(config.url)

        ws.onmessage = (event) => {
          const message = JSON.parse(event.data)

          switch (message.type) {
            case 'initial':
              message.data.forEach((item: TData) => {
                collection.utils.directWrite('insert', item)
              })
              break
            case 'insert':
              collection.utils.directWrite('insert', message.data)
              break
            case 'update':
              collection.utils.directWrite('update', message.data)
              break
            case 'delete':
              collection.utils.directWrite('delete', message.key)
              break
          }
        }

        return () => ws.close()
      },
    },

    onInsert:
      config.onInsert ??
      (async ({ transaction }) => {
        // Default: send via WebSocket
        ws.send(
          JSON.stringify({
            type: 'insert',
            data: transaction.mutations.map((m) => m.modified),
          }),
        )
      }),

    onUpdate: config.onUpdate,
    onDelete: config.onDelete,
  }
}
```

## Example: IndexedDB Collection

```tsx
import { openDB, type IDBPDatabase } from 'idb'

export function indexedDBCollectionOptions<TData, TKey>(config: {
  id: string
  dbName: string
  storeName: string
  getKey: (item: TData) => TKey
  schema?: StandardSchema
}): CollectionOptions<TData, TKey> {
  let db: IDBPDatabase

  return {
    id: config.id,
    getKey: config.getKey,
    schema: config.schema,

    sync: {
      start: async (collection) => {
        db = await openDB(config.dbName, 1, {
          upgrade(db) {
            db.createObjectStore(config.storeName, {
              keyPath: 'id',
            })
          },
        })

        // Load initial data
        const items = await db.getAll(config.storeName)
        items.forEach((item) => {
          collection.utils.directWrite('insert', item)
        })
      },

      stop: async () => {
        db?.close()
      },
    },

    onInsert: async ({ transaction }) => {
      const tx = db.transaction(config.storeName, 'readwrite')
      await Promise.all(
        transaction.mutations.map((m) => tx.store.add(m.modified)),
      )
      await tx.done
    },

    onUpdate: async ({ transaction }) => {
      const tx = db.transaction(config.storeName, 'readwrite')
      await Promise.all(
        transaction.mutations.map((m) => tx.store.put(m.modified)),
      )
      await tx.done
    },

    onDelete: async ({ transaction }) => {
      const tx = db.transaction(config.storeName, 'readwrite')
      await Promise.all(
        transaction.mutations.map((m) => tx.store.delete(m.key as IDBValidKey)),
      )
      await tx.done
    },
  }
}
```

## Direct Write API

Use `directWrite` to update collection from external sources:

```tsx
// Insert item(s)
collection.utils.directWrite('insert', item)
collection.utils.directWrite('insert', [item1, item2])

// Update item(s)
collection.utils.directWrite('update', updatedItem)

// Delete by key
collection.utils.directWrite('delete', key)
collection.utils.directWrite('delete', [key1, key2])
```

## Collection State

Track collection status:

```tsx
interface CollectionState {
  isLoading: boolean
  isError: boolean
  error?: Error
  isSyncing: boolean
}

// Access in components
const state = myCollection.state
if (state.isLoading) return <Loading />
if (state.isError) return <Error error={state.error} />
```

## Testing Custom Collections

```tsx
import { createCollection } from '@tanstack/db'

describe('MyCustomCollection', () => {
  it('loads initial data', async () => {
    const collection = createCollection(
      myCollectionOptions({
        id: 'test',
        getKey: (item) => item.id,
        // ... test config
      }),
    )

    // Wait for sync
    await waitFor(() => collection.size > 0)

    expect(collection.toArray).toHaveLength(expectedCount)
  })
})
```

## Reference Implementations

Study existing implementations:

- `@tanstack/query-db-collection` - REST API integration
- `@tanstack/electric-db-collection` - Real-time sync
- Built-in `localOnlyCollectionOptions` - Simple in-memory
- Built-in `localStorageCollectionOptions` - Browser persistence

# Electric Collection

Real-time sync from Postgres via ElectricSQL.

## Installation

```bash
npm install @tanstack/electric-db-collection @tanstack/react-db
```

## Basic Setup

```tsx
import { createCollection } from '@tanstack/react-db'
import { electricCollectionOptions } from '@tanstack/electric-db-collection'

const todoCollection = createCollection(
  electricCollectionOptions({
    id: 'todos',
    getKey: (item) => item.id,
    shapeOptions: {
      url: '/api/todos', // Your Electric proxy
    },
  }),
)
```

## Configuration Options

```tsx
electricCollectionOptions({
  // Required
  getKey: (item) => Key,        // Extract unique key
  shapeOptions: {
    url: string,                // Electric proxy URL
    params?: Record<string, string>, // Additional params
  },

  // Optional
  id?: string,                  // Collection identifier
  schema?: StandardSchema,      // Validation schema

  // Mutation handlers
  onInsert?: MutationFn,
  onUpdate?: MutationFn,
  onDelete?: MutationFn,
})
```

## Shapes

Shapes define what data syncs. Configure in your proxy:

| Parameter | Description    | Example             |
| --------- | -------------- | ------------------- |
| `table`   | Postgres table | `todos`             |
| `where`   | Row filter     | `user_id = $1`      |
| `columns` | Column filter  | `id,text,completed` |

**Note:** Configure shapes server-side for security, not client-side.

## Txid Matching

Return transaction IDs to wait for sync:

```tsx
onInsert: async ({ transaction }) => {
  const item = transaction.mutations[0].modified
  const response = await api.todos.create(item)
  return { txid: response.txid }
}
```

Backend must return txid from the same transaction as the mutation:

```typescript
async function createTodo(data: TodoInput) {
  let txid: number

  await db.transaction(async (tx) => {
    // Get txid INSIDE the transaction
    const result = await tx.execute(
      sql`SELECT pg_current_xact_id()::xid::text as txid`,
    )
    txid = parseInt(result.rows[0].txid, 10)

    await tx.execute(sql`INSERT INTO todos ${tx(data)}`)
  })

  return { txid }
}
```

## Custom Match Functions

When txids aren't available:

```tsx
import { isChangeMessage } from '@tanstack/electric-db-collection'

onInsert: async ({ transaction, collection }) => {
  const item = transaction.mutations[0].modified
  await api.todos.create(item)

  await collection.utils.awaitMatch(
    (message) =>
      isChangeMessage(message) &&
      message.headers.operation === 'insert' &&
      message.value.text === item.text,
    5000, // timeout ms
  )
}
```

## Utility Methods

```tsx
// Wait for specific txid
await collection.utils.awaitTxId(12345)
await collection.utils.awaitTxId(12345, 10000) // with timeout

// Wait for custom match
await collection.utils.awaitMatch(matchFn, timeout)
```

## Helper Functions

```tsx
import {
  isChangeMessage,
  isControlMessage,
} from '@tanstack/electric-db-collection'

// Check message type
if (isChangeMessage(message)) {
  // message.headers.operation: 'insert' | 'update' | 'delete'
  // message.value: the row data
}

if (isControlMessage(message)) {
  // 'up-to-date' or 'must-refetch'
}
```

## Proxy Example

```typescript
// routes/api/todos.ts
import { ELECTRIC_PROTOCOL_QUERY_PARAMS } from '@electric-sql/client'

const ELECTRIC_URL = 'http://localhost:3000/v1/shape'

export async function GET(request: Request) {
  // Auth check
  const user = await getUser(request)
  if (!user) return new Response('Unauthorized', { status: 401 })

  const url = new URL(request.url)
  const originUrl = new URL(ELECTRIC_URL)

  // Pass through Electric params
  url.searchParams.forEach((value, key) => {
    if (ELECTRIC_PROTOCOL_QUERY_PARAMS.includes(key)) {
      originUrl.searchParams.set(key, value)
    }
  })

  // Set shape (server-controlled)
  originUrl.searchParams.set('table', 'todos')
  originUrl.searchParams.set('where', `user_id = '${user.id}'`)

  const response = await fetch(originUrl)
  const headers = new Headers(response.headers)
  headers.delete('content-encoding')
  headers.delete('content-length')

  return new Response(response.body, {
    status: response.status,
    headers,
  })
}
```

## Debugging

Enable debug logging:

```javascript
localStorage.debug = 'ts/db:electric'
```

Common debug output:

```
// Working correctly
ts/db:electric awaitTxId called with txid 123
ts/db:electric new txids synced from pg [123]
ts/db:electric awaitTxId found match for txid 123

// Txid mismatch (common bug)
ts/db:electric awaitTxId called with txid 124
ts/db:electric new txids synced from pg [123]
// Stalls forever - 124 never arrives
```

## With Custom Actions

```tsx
const addTodo = createOptimisticAction<{ text: string }>({
  onMutate: ({ text }) => {
    todoCollection.insert({
      id: crypto.randomUUID(),
      text,
      completed: false,
    })
  },
  mutationFn: async ({ text }) => {
    const response = await api.todos.create({ text })
    await todoCollection.utils.awaitTxId(response.txid)
  },
})
```

## Real-Time Updates

Electric automatically streams changes. No polling needed:

```tsx
// Changes sync automatically when:
// 1. Another user modifies data
// 2. Backend process updates database
// 3. Database trigger fires

// Your live queries update automatically
const { data } = useLiveQuery((q) => q.from({ todo: todoCollection }))
// `data` updates in real-time
```

# Local Collections

In-memory and localStorage-backed collections for client-only state.

## LocalOnlyCollection

In-memory state, lost on refresh:

```tsx
import {
  createCollection,
  localOnlyCollectionOptions,
} from '@tanstack/react-db'

const uiStateCollection = createCollection(
  localOnlyCollectionOptions({
    id: 'ui-state',
    getKey: (item) => item.id,
  }),
)

// Use for temporary state
uiStateCollection.insert({ id: 'sidebar', expanded: true })
uiStateCollection.insert({ id: 'modal', open: false })

// Query like any collection
const { data } = useLiveQuery((q) => q.from({ state: uiStateCollection }))
```

## LocalStorageCollection

Persists to localStorage, syncs across tabs:

```tsx
import {
  createCollection,
  localStorageCollectionOptions,
} from '@tanstack/react-db'

const settingsCollection = createCollection(
  localStorageCollectionOptions({
    id: 'user-settings',
    storageKey: 'app-settings', // localStorage key
    getKey: (item) => item.id,
  }),
)

// Persists across sessions
settingsCollection.insert({ id: 'theme', value: 'dark' })
settingsCollection.insert({ id: 'language', value: 'en' })

// Syncs across browser tabs automatically
```

## Configuration

```tsx
localOnlyCollectionOptions({
  id: string,                   // Collection identifier
  getKey: (item) => Key,        // Extract unique key
  schema?: StandardSchema,      // Optional validation
})

localStorageCollectionOptions({
  id: string,                   // Collection identifier
  storageKey: string,           // localStorage key
  getKey: (item) => Key,        // Extract unique key
  schema?: StandardSchema,      // Optional validation
})
```

## No Mutation Handlers

Local collections don't need `onInsert`/`onUpdate`/`onDelete` since there's no server. Mutations apply directly.

```tsx
// Just works, no handlers needed
settingsCollection.update('theme', (draft) => {
  draft.value = 'light'
})
```

## Side Effect Handlers

You can add handlers for side effects (analytics, logging):

```tsx
const settingsCollection = createCollection(
  localStorageCollectionOptions({
    id: 'settings',
    storageKey: 'app-settings',
    getKey: (item) => item.id,

    onUpdate: async ({ transaction }) => {
      // Side effect: track setting changes
      analytics.track('setting_changed', {
        setting: transaction.mutations[0].key,
        newValue: transaction.mutations[0].modified.value,
      })
    },
  }),
)
```

## With Manual Transactions

Local collections require `acceptMutations` in manual transactions:

```tsx
const tx = createTransaction({
  autoCommit: false,
  mutationFn: async ({ transaction }) => {
    // For server collections: call API
    await api.save(...)

    // For local collections: accept mutations
    settingsCollection.utils.acceptMutations(transaction)
  },
})

tx.mutate(() => {
  settingsCollection.update('theme', (d) => { d.value = 'dark' })
})

await tx.commit()
```

## Mixing Local and Server Collections

Same transaction can modify both:

```tsx
const tx = createTransaction({
  autoCommit: false,
  mutationFn: async ({ transaction }) => {
    // Server collection mutations
    const serverMutations = transaction.mutations.filter(
      (m) => m.collection !== localSettings,
    )
    if (serverMutations.length > 0) {
      await api.save(serverMutations)
    }

    // Local collection mutations
    localSettings.utils.acceptMutations(transaction)
  },
})

tx.mutate(() => {
  // Server
  userProfile.update('user-1', (d) => {
    d.name = 'New Name'
  })
  // Local
  localSettings.update('theme', (d) => {
    d.value = 'dark'
  })
})

await tx.commit()
```

## Cross-Tab Sync (LocalStorage)

LocalStorageCollection automatically syncs across tabs:

```tsx
// Tab 1
settingsCollection.update('theme', (d) => {
  d.value = 'dark'
})

// Tab 2 - automatically receives the update
// Live queries update reactively
```

## Storage Limits

localStorage has ~5MB limit per origin. For larger data:

- Consider IndexedDB (via RxDBCollection or custom)
- Split into multiple collections
- Store references, not full data

## Use Cases

| Collection   | Use Case                                  |
| ------------ | ----------------------------------------- |
| LocalOnly    | Modal state, form drafts, temp selections |
| LocalStorage | User preferences, theme, recently viewed  |

## Schema Validation

Both support schema validation:

```tsx
const settingsSchema = z.object({
  id: z.string(),
  value: z.union([z.string(), z.number(), z.boolean()]),
  updatedAt: z.date().default(() => new Date()),
})

const settingsCollection = createCollection(
  localStorageCollectionOptions({
    id: 'settings',
    storageKey: 'app-settings',
    getKey: (item) => item.id,
    schema: settingsSchema,
  }),
)
```

## Clearing Data

```tsx
// Delete all items
const items = settingsCollection.toArray
items.forEach((item) => settingsCollection.delete(item.id))

// Or directly clear localStorage (LocalStorageCollection)
localStorage.removeItem('app-settings')
```

# Query Collection

Load data from REST APIs using TanStack Query.

## Installation

```bash
npm install @tanstack/query-db-collection @tanstack/react-db @tanstack/react-query
```

## Basic Setup

```tsx
import { createCollection } from '@tanstack/react-db'
import { queryCollectionOptions } from '@tanstack/query-db-collection'
import { QueryClient } from '@tanstack/react-query'

const queryClient = new QueryClient()

const todoCollection = createCollection(
  queryCollectionOptions({
    queryKey: ['todos'],
    queryFn: async () => {
      const response = await fetch('/api/todos')
      return response.json()
    },
    getKey: (item) => item.id,
    queryClient,
  }),
)
```

## Configuration Options

```tsx
queryCollectionOptions({
  // Required
  queryKey: QueryKey,           // TanStack Query cache key
  queryFn: QueryFn,             // Data fetching function
  getKey: (item) => Key,        // Extract unique key from item

  // Optional
  queryClient?: QueryClient,    // Your query client instance
  schema?: StandardSchema,      // Validation schema
  syncMode?: 'eager' | 'on-demand' | 'progressive',

  // Mutation handlers
  onInsert?: MutationFn,
  onUpdate?: MutationFn,
  onDelete?: MutationFn,
})
```

## Predicate Push-Down

With `syncMode: 'on-demand'`, query predicates are passed to your queryFn:

```tsx
const productsCollection = createCollection(
  queryCollectionOptions({
    queryKey: ['products'],
    queryFn: async (ctx) => {
      // ctx.meta.loadSubsetOptions contains query predicates
      const params = parseLoadSubsetOptions(ctx.meta?.loadSubsetOptions)
      // params: { where: { category: 'electronics', price_lt: 100 }, limit: 50 }

      const url = new URL('/api/products')
      if (params.where?.category) {
        url.searchParams.set('category', params.where.category)
      }
      if (params.where?.price_lt) {
        url.searchParams.set('price_lt', params.where.price_lt)
      }
      if (params.limit) {
        url.searchParams.set('limit', params.limit)
      }

      return fetch(url).then((r) => r.json())
    },
    getKey: (item) => item.id,
    syncMode: 'on-demand',
  }),
)

// This query triggers API call with predicates
const { data } = useLiveQuery((q) =>
  q
    .from({ product: productsCollection })
    .where(({ product }) => eq(product.category, 'electronics'))
    .where(({ product }) => lt(product.price, 100))
    .limit(50),
)
```

## Delta Loading

QueryCollection automatically handles delta loading:

```tsx
// First query loads: category=electronics
const q1 = q.where(({ p }) => eq(p.category, 'electronics'))

// Second query expands: category=electronics OR category=clothing
// Only loads clothing items, keeps electronics from cache
const q2 = q.where(({ p }) =>
  or(eq(p.category, 'electronics'), eq(p.category, 'clothing')),
)
```

## Refetching

```tsx
// Manual refetch
await todoCollection.utils.refetch()

// Refetch on window focus (via TanStack Query)
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: true,
    },
  },
})
```

## Direct Writes

For real-time updates (WebSocket, SSE), write directly to collection:

```tsx
// Listen to real-time updates
websocket.on('todo:created', (todo) => {
  todoCollection.utils.directWrite('insert', todo)
})

websocket.on('todo:updated', (todo) => {
  todoCollection.utils.directWrite('update', todo)
})

websocket.on('todo:deleted', ({ id }) => {
  todoCollection.utils.directWrite('delete', id)
})
```

## With TanStack Query Hooks

Access underlying query state:

```tsx
import { useQuery } from '@tanstack/react-query'

function TodoStats() {
  const { isLoading, isError, dataUpdatedAt } = useQuery({
    queryKey: ['todos'],
    // Query is managed by collection, this just accesses state
  })

  return (
    <div>
      {isLoading && <span>Loading...</span>}
      {isError && <span>Error loading todos</span>}
      <span>Last updated: {new Date(dataUpdatedAt).toLocaleString()}</span>
    </div>
  )
}
```

## Mutation Handlers

QueryCollection auto-refetches after handlers complete:

```tsx
queryCollectionOptions({
  onInsert: async ({ transaction }) => {
    await fetch('/api/todos', {
      method: 'POST',
      body: JSON.stringify(transaction.mutations[0].modified),
    })
    // Auto-refetch happens after this returns
  },

  onUpdate: async ({ transaction }) => {
    const { original, changes } = transaction.mutations[0]
    await fetch(`/api/todos/${original.id}`, {
      method: 'PATCH',
      body: JSON.stringify(changes),
    })
  },

  onDelete: async ({ transaction }) => {
    await fetch(`/api/todos/${transaction.mutations[0].original.id}`, {
      method: 'DELETE',
    })
  },
})
```

## Stale Time and Caching

Control cache behavior via TanStack Query options:

```tsx
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      gcTime: 10 * 60 * 1000, // 10 minutes
    },
  },
})
```

## Error Handling

```tsx
const todoCollection = createCollection(
  queryCollectionOptions({
    queryFn: async () => {
      const response = await fetch('/api/todos')
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`)
      }
      return response.json()
    },
  }),
)

// Check collection state
if (todoCollection.state.isError) {
  console.log(todoCollection.state.error)
}
```

## Multiple Query Keys

For filtered views, use different query keys:

```tsx
const activeTodos = createCollection(
  queryCollectionOptions({
    queryKey: ['todos', 'active'],
    queryFn: () => fetch('/api/todos?status=active').then((r) => r.json()),
    getKey: (item) => item.id,
  }),
)

const completedTodos = createCollection(
  queryCollectionOptions({
    queryKey: ['todos', 'completed'],
    queryFn: () => fetch('/api/todos?status=completed').then((r) => r.json()),
    getKey: (item) => item.id,
  }),
)
```

# Sync Modes

Control how data loads into QueryCollections.

## Overview

| Mode          | Load Behavior                         | Best For                   |
| ------------- | ------------------------------------- | -------------------------- |
| `eager`       | Load all upfront                      | Small datasets (<10k rows) |
| `on-demand`   | Load only what queries request        | Large datasets (>50k rows) |
| `progressive` | Load subset first, full in background | Collaborative apps         |

## Eager Mode (Default)

Loads entire dataset on first access:

```tsx
const todoCollection = createCollection(
  queryCollectionOptions({
    queryKey: ['todos'],
    queryFn: async () => api.todos.getAll(),
    getKey: (item) => item.id,
    syncMode: 'eager', // Default
  }),
)
```

**Pros:**

- Simplest mental model
- All data available immediately for queries
- No network requests when filtering/sorting

**Cons:**

- Slow initial load for large datasets
- Memory usage for full dataset

**Best for:**

- User preferences
- Small reference tables
- Data that's mostly accessed

## On-Demand Mode

Loads only what queries request:

```tsx
const productsCollection = createCollection(
  queryCollectionOptions({
    queryKey: ['products'],
    queryFn: async (ctx) => {
      const params = parseLoadSubsetOptions(ctx.meta?.loadSubsetOptions)
      return api.products.search(params)
    },
    getKey: (item) => item.id,
    syncMode: 'on-demand',
  }),
)

// Only loads electronics products
const { data } = useLiveQuery((q) =>
  q
    .from({ product: productsCollection })
    .where(({ product }) => eq(product.category, 'electronics'))
    .limit(50),
)
```

**Pros:**

- Fast initial load
- Low memory usage
- Scales to any dataset size

**Cons:**

- Network request on each new query pattern
- Can't query data that isn't loaded

**Best for:**

- Product catalogs
- Search interfaces
- Large datasets where most data isn't accessed

## Progressive Mode

Loads query subset immediately, syncs full dataset in background:

```tsx
const issuesCollection = createCollection(
  queryCollectionOptions({
    queryKey: ['issues'],
    queryFn: async (ctx) => {
      if (ctx.meta?.loadSubsetOptions) {
        // First: load what query needs
        return api.issues.search(
          parseLoadSubsetOptions(ctx.meta.loadSubsetOptions),
        )
      }
      // Then: load everything in background
      return api.issues.getAll()
    },
    getKey: (item) => item.id,
    syncMode: 'progressive',
  }),
)
```

**Pros:**

- Instant first paint
- Eventually has all data for fast local queries
- Good for collaborative apps

**Cons:**

- More complex implementation
- Uses more memory than on-demand

**Best for:**

- Issue trackers (like Linear)
- Collaborative documents
- Apps that benefit from local-first after initial sync

## Predicate Push-Down

With `on-demand` and `progressive`, query predicates are passed to queryFn:

```tsx
queryFn: async (ctx) => {
  const options = ctx.meta?.loadSubsetOptions
  // options contains:
  // - where: query conditions
  // - limit: row limit
  // - offset: pagination offset
  // - orderBy: sort specification

  const params = parseLoadSubsetOptions(options)
  return api.fetch(params)
}
```

### parseLoadSubsetOptions

Helper to convert predicates to API params:

```tsx
import { parseLoadSubsetOptions } from '@tanstack/query-db-collection'

const params = parseLoadSubsetOptions(ctx.meta?.loadSubsetOptions)
// {
//   where: { category: 'electronics', price_lt: 100 },
//   limit: 50,
//   offset: 0,
//   orderBy: [{ field: 'price', direction: 'asc' }]
// }
```

## Delta Loading

TanStack DB automatically optimizes loading:

```tsx
// First query loads category=electronics
const q1 = q.where(({ p }) => eq(p.category, 'electronics'))

// Second query expands to include clothing
const q2 = q.where(({ p }) =>
  or(eq(p.category, 'electronics'), eq(p.category, 'clothing')),
)
// Only loads clothing, keeps electronics from cache
```

## Choosing a Mode

```
┌─────────────────────────────────────────────────────────────┐
│                    How much data?                           │
└─────────────────────────────────────────────────────────────┘
                              │
              ┌───────────────┼───────────────┐
              │               │               │
         < 10k rows      10k-50k rows     > 50k rows
              │               │               │
              ▼               ▼               ▼
           EAGER         PROGRESSIVE      ON-DEMAND
```

**Additional considerations:**

- Need instant filtering on all data? → eager or progressive
- Search/filter is primary use case? → on-demand
- Collaborative with real-time updates? → progressive
- Memory-constrained environment? → on-demand

## Combining Modes

Different collections can use different modes:

```tsx
// Small reference data: eager
const categoriesCollection = createCollection(
  queryCollectionOptions({
    syncMode: 'eager',
    ...
  })
)

// Large catalog: on-demand
const productsCollection = createCollection(
  queryCollectionOptions({
    syncMode: 'on-demand',
    ...
  })
)

// Collaborative data: progressive
const issuesCollection = createCollection(
  queryCollectionOptions({
    syncMode: 'progressive',
    ...
  })
)
```

